<?php
declare(strict_types=1);
require_once __DIR__.'/legacy-migration/ActiveBaselineOperationalCaseConnector.php';
function envRequired(string$name):string{$value=getenv($name);if(!is_string($value)||$value==='')throw new RuntimeException("{$name} is required");return$value;}
function processPrefix():string{$configured=getenv('FMONITOR_PROCESS_TABLE_PREFIX');if(is_string($configured)&&preg_match('/^[A-Za-z0-9_]+$/D',$configured)===1)return$configured;$files=glob('/home/fmonitor/.local/state/fmonitor2/pilot-demo/*/active.json')?:[];if(count($files)!==1)throw new RuntimeException('Exactly one active local pilot manifest is required');$manifest=json_decode((string)file_get_contents($files[0]),true,flags:JSON_THROW_ON_ERROR);$prefix=$manifest['processPrefix']??null;if(!is_string($prefix)||preg_match('/^[A-Za-z0-9_]+$/D',$prefix)!==1||($manifest['state']??null)!=='ready')throw new RuntimeException('Active local pilot manifest is invalid');return$prefix;}
$o=getopt('',['legacy-object-id:','all','apply','after-id::','batch-size::']);$single=isset($o['legacy-object-id'])?(int)$o['legacy-object-id']:null;$all=isset($o['all']);if(($single!==null)===$all)throw new InvalidArgumentException('Choose exactly one of --legacy-object-id or --all');$after=max(0,(int)($o['after-id']??0));$size=(int)($o['batch-size']??50);if($size<1||$size>100)throw new InvalidArgumentException('batch-size must be 1..100');$apply=isset($o['apply']);$prefix=processPrefix();$db=new mysqli(getenv('FMONITOR_DB_HOST')?:envRequired('FMONITOR_DEMO_DB_HOST'),getenv('FMONITOR_DB_USER')?:envRequired('FMONITOR_DEMO_DB_USER'),getenv('FMONITOR_DB_PASSWORD')?:envRequired('FMONITOR_DEMO_DB_PASSWORD'),getenv('FMONITOR_DB_NAME')?:envRequired('FMONITOR_DEMO_DB_NAME'),(int)(getenv('FMONITOR_DB_PORT')?:getenv('FMONITOR_DEMO_DB_PORT')?:3306));$db->set_charset('utf8mb4');$connector=new ActiveBaselineOperationalCaseConnector($db,$prefix);$at=gmdate(DATE_ATOM);
try{$ids=[];if($single!==null)$ids=[$single];else{$s=$db->prepare("SELECT legacy_object_id FROM `{$prefix}fm2_legacy_active_baselines` WHERE legacy_object_id>? ORDER BY legacy_object_id LIMIT ?");$s->bind_param('ii',$after,$size);$s->execute();$ids=array_map('intval',array_column($s->get_result()->fetch_all(MYSQLI_ASSOC),'legacy_object_id'));}$results=[];$stats=['scanned'=>0,'wouldCreate'=>0,'created'=>0,'alreadyConnected'=>0,'blocked'=>0];foreach($ids as$id){$stats['scanned']++;try{$result=$connector->connect($id,$apply,$at);$results[]=['legacyObjectId'=>$id,'status'=>$result['status'],'caseId'=>$result['caseId'],'baselineHash'=>$result['baselineHash'],'templateContentSha256'=>$result['templateContentSha256']];$key=match($result['status']){'would_create'=>'wouldCreate','created'=>'created',default=>'alreadyConnected'};$stats[$key]++;}catch(DomainException$error){$stats['blocked']++;$results[]=['legacyObjectId'=>$id,'status'=>'blocked','reason'=>$error->getMessage()];}}$next=$ids===[]?$after:max($ids);echo json_encode(['ok'=>$stats['blocked']===0,'mode'=>$apply?'apply':'dry-run','connectorVersion'=>ActiveBaselineOperationalCaseConnector::VERSION,'startedAfterId'=>$after,'nextAfterId'=>$next,'complete'=>!$all||count($ids)<$size,'stats'=>$stats,'results'=>$results],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";}finally{$db->close();}
